# Pull out the most impaired patients, then look at the extremes of hippocampal
# volume across the whole cohort.
# 
severe <- subset(memclinic, group == "___" & moca < ___)
nrow(severe)

severe[order(severe$___), c("id", "moca", "hippo_vol_mm3")]

biggest <- memclinic[order(-memclinic$hippo_vol_mm3), ]
head(biggest[, c("id", "group", "hippo_vol_mm3")], 5)

