# ---- Exercise 5 — wide to long -------------------------------------------------
# 
stroop <- read.csv("data/___.csv")
nrow(stroop)

long <- reshape(stroop,
                direction = "long",
                varying   = c("rt_congruent", "rt_neutral", "rt_incongruent"),
                v.names   = "rt",
